head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};

// 사전 조건 : 2행 세팅 + Column 인덱스 1(textImage) 의 두 Row 에 Body Cell imageSrc 설정(제거 대상 확보)
scwin.onpageload = function () {
    dlt_bind.setJSON([{ col1: "A1", col2: "B1" }, { col1: "A2", col2: "B2" }], false);
    target1.setCellImageSrc(0, 1, "/cm/images/base/ico_grid_add.svg");
    target1.setCellImageSrc(1, 1, "/cm/images/base/ico_grid_add.svg");
};

// 유효하지 않은 columnInfo 로 removeCellImageSrc 를 호출하고 반환값을 출력
scwin.runInvalidColumnInfo = function (columnInfo, strCall) {
    var rtn = target1.removeCellImageSrc(0, columnInfo);
    scwin.setReturnValue(strCall + " : [기대] false   [실제] " + rtn + (rtn === true ? "   => 결함" : ""));
};

// [재현 버튼] 존재하지 않는 Column 인덱스(99) 를 columnInfo 로 전달
scwin.btn_invalidCol_onclick = function () {
    scwin.runInvalidColumnInfo(99, "removeCellImageSrc(0, 99)");
};

// [재현 버튼] 존재하지 않는 Column ID('noSuchColumn') 를 columnInfo 로 전달
scwin.btn_invalidColId_onclick = function () {
    scwin.runInvalidColumnInfo("noSuchColumn", "removeCellImageSrc(0, 'noSuchColumn')");
};
